insert into public.auction_items (title,description,starting_price,sort_order) values
('Busto de Francisco Morazán','Busto conmemorativo del General Francisco Morazán, obra escultórica del QH:. Emilio España Core. Pieza única de 48 cm de altura, elaborada con acabado en pátina bronce sobre base tallada. Un homenaje al prócer centroamericano y símbolo de los ideales de libertad y unión que inspiran a la Masonería hondureña. Pieza de colección donada especialmente para esta subasta benéfica.',1200,1),
('Cigarrera Clásica de Bolsillo con Emblema Masónico','Exclusiva pieza de colección y uso personal que combina elegancia atemporal, funcionalidad y distinción fraternal. Esta cigarrera rígida de perfil ultrafino presenta una cubierta texturizada en tono oscuro enmarcada en metal pulido, realzada en el centro por el medallón dorado de la Escuadra y el Compás con la letra «G».',550,2),
('Sticker Masónico Premium para Vehículo (14 cm × 13.5 cm)','Extraordinaria pieza de distinción automotriz en subasta. Este emblema de gran formato destaca por su imponente presencia visual, la representación exacta de la Escuadra, el Compás y la letra «G», concebido para miembros de la orden y coleccionistas que buscan portar el símbolo fraternal con elegancia y máxima calidad en sus vehículos.',150,3),
('Escultura Alegórica «El Hombre Esculpiéndose a Sí Mismo»','Magna pieza decorativa de alto valor simbólico y filosófico. Inspirada en la icónica alegoría del Self-Made Man, esta escultura representa la figura de un hombre tallando su propio cuerpo desde un bloque de roca bruta utilizando el mazo y el cincel. Una obra cargada de significado sobre la superación personal, la autodisciplina y el perfeccionamiento continuo, altamente apreciada tanto en logias y despachos como en bibliotecas o salas de estudio.',560,4),
('Estuche Metálico Deslizante con Medallón Masónico Ilustrado','Accesorio de bolsillo funcional y sobrio que fusiona la comodidad del formato compacto con una detallada representación de la iconografía tradicional masónica. Confeccionado en cuerpo metálico rígido negro mate con mecanismo de apertura deslizante, este estuche destaca por su medallón central policromado en tonos dorados y azul cobalto, en el que se aprecian la Escuadra, el Compás, el ancla y la corona circular con inscripciones y simbología fraternal.',420,5),
('Gorra Clásica Vintage con Emblema Masónico','Exclusivo accesorio de vestimenta casual que fusiona el estilo vintage contemporáneo con la solemnidad de la tradición masónica. Confeccionada en algodón lavado con efecto desgastado (washed denim/cotton), esta gorra presenta en su panel frontal el símbolo de la Escuadra y el Compás, ideal para portar identidad fraternal con sobriedad y distinción en el día a día.',450,6),
('Lote Exclusivo: 20 Pines con Emblema Masónico','Distinción, tradición y solemnidad en un solo set. Este lote de 20 broches tipo pin presenta el icónico símbolo de la Escuadra, el Compás y la letra «G», elaborado con acabados de alta definición y brillo refinado. Es una pieza fundamental pensada para miembros de la orden, dignatarios de logias, eventos conmemorativos y coleccionistas exigentes de la simbología fraternal.',480,7),
('Maletín Ejecutivo Porta Laptop Masónico Serie Freestyle','Elegante maletín ejecutivo de diseño contemporáneo, concebido para brindar máxima funcionalidad, protección y distinción en el entorno profesional y ceremonial. Destaca por su moderno patrón geométrico tipo panal en acabado carbón texturizado y el emblemático sello central que enmarca la Escuadra, el Compás y la letra «G» en finos contrastes dorados y plateados.',660,8),
('Maletín para Laptop con Emblema Masónico - Modelo J6','Subastamos este elegante maletín para laptop, modelo J6, que presenta el icónico emblema masónico. Una pieza única que combina practicidad y simbolismo, ideal para miembros de la orden o coleccionistas. Confeccionado con materiales de primera calidad, este maletín ofrece durabilidad, ligereza y una gran capacidad de almacenamiento.',780,9),
('Masones en las Letras — Nicolás Brihuega','Libro "Masones en las Letras" del autor Nicolás Brihuega. Obra literaria de 148 páginas que explora la profunda influencia de los masones en el mundo de las letras, la filosofía y las artes. Una lectura obligada para el hermano interesado en el legado cultural e intelectual de la Orden.',500,10),
('Pin de Solapa Masónico con Forma de Trulla Esmaltada (3 unidades)','Insignia ceremonial y de vestimenta formal inspirada en una de las herramientas de trabajo más representativas de la francmasonería: la llana o trulla (trowel), símbolo de la unión fraternal y la cohesión. Fabricada en aleación metálica con baño dorado pulido, presenta el cuerpo triangular esmaltado en azul cobalto brillante con el emblema de la Escuadra, el Compás y la letra «G» finamente grabados en relieve dorado.',120,11),
('Pin Oficial de la Orden DeMolay','Pin oficial de la Orden DeMolay, insignia de solapa de metal esmaltado con los símbolos característicos de la Orden. Pieza de colección ideal para hermanos, asesores y padrinos que deseen portar con orgullo el emblema DeMolay en eventos formales.',500,12),
('Pisacorbatas Masónico','Pisacorbatas con el emblema de la Escuadra y el Compás, elaborado artesanalmente en plata sólida .925. Accesorio elegante y discreto para complementar el atuendo formal masónico en tenidas, ágapes y eventos institucionales.',300,13),
('Pulsera de Cuero Marrón con Símbolo Masónico en Cabujón de Vidrio','Lleva contigo un accesorio con carácter, elegancia y profundo simbolismo. Esta pulsera combina la calidez del cuero artesanal con el misticismo del emblema masónico protegido bajo una cúpula de vidrio brillante, ideal para complementar cualquier estilo diario o para una ocasión especial.',280,14),
('Reloj de Bolsillo Vintage con Simbología Masónica en Relieve (Acabado Bronce)','Una pieza de colección cargada de historia, arte y tradición. Este magnífico reloj de bolsillo de estilo clásico destaca por su tapa frontal finamente labrada en alto relieve con las herramientas e insignias esenciales de la orden: la Escuadra, el Compás, la letra «G», el Ojo que Todo lo Ve irradiando luz, la Plomada, el Nivel, la Llana y el Mallete. Un reloj que fusiona precisión moderna y estética ceremonial de época.',470,15),
('Set de 10 Broches de Solapa con Emblema Masónico Troquelado','Distinguido lote ceremonial y de vestimenta formal compuesto por 10 pines metálicos de alta calidad. Cada pieza está elaborada con la silueta troquelada de la Escuadra y el Compás, enmarcando con precisión la letra «G» central sobre fondo contrastante. Un conjunto esencial y solemne, pensado para dignatarios, miembros de la orden, eventos masónicos conmemorativos o coleccionistas de insignias fraternales.',350,16),
('Set de 3 Broches Masónicos de Solapa','Distinguida colección de tres insignias solaperas que representan los principios y lemas más representativos de la tradición masónica universal. Este conjunto reúne tres piezas únicas con acabados esmaltados y troquelados de alta precisión: el emblema clásico en filigrana, el medallón de los Antiguos Masones Libres y Aceptados, y el distintivo con la célebre divisa «Ordo Ab Chao».',330,17),
('Set de 4 Stickers Masónicos para Vehículo (3 Pulgadas) – «Fe, Esperanza y Caridad»','Exclusivo lote de cuatro medallones automotrices de alta gama. Cada pieza presenta un diseño circular en relieve con los símbolos cardinales de la Escuadra, el Compás y la letra «G», enmarcados con la inscripción de las tres virtudes teologales: «Fe, Esperanza y Caridad». Una oportunidad ideal para miembros de la orden, logias o coleccionistas que buscan portar o compartir estos emblemas fraternales con el más alto nivel de presencia y durabilidad.',300,18),
('Set de 5 Pines Masónicos de Solapa – Escuadra, Compás y Letra «G»','Elegante lote compuesto por 5 broches metálicos de solapa en formato mini/discreto, diseñados con la silueta clásica e inconfundible de la Escuadra y el Compás. Cada insignia resalta por su fondo interior esmaltado en azul cobalto profundo, sobre el cual resalta la letra «G» en relieve dorado brillante. Un conjunto uniforme y sobrio, ideal para miembros de taller, eventos protocolarios o coleccionismo.',220,19),
('Set Exclusivo Masónico de Billetera y Cinturón en Cuero Vintage – Edición Ejecutiva','Eleva tu estilo cotidiano y profesional con este elegante set masculino de dos piezas. Diseñado para combinar sobriedad, distinción y practicidad, este conjunto integra un acabado clásico con detalles discretos de simbología masónica, logrando el equilibrio perfecto entre tradición y distinción ejecutiva.',450,20),
('Pulsera en silicón y metal con el logo de DeMolay International','Pulsera elaborada en silicón y metal con el logo de DeMolay International. Accesorio cómodo y de uso diario, ideal para jóvenes miembros y simpatizantes de la Orden.',150,44),
('Moneda grande que por un lado tiene el logo de la Gran Logia Cuscatlán y por el otro el logo del COMACA LVII','Moneda conmemorativa de gran formato, que en una cara luce el logo de la Gran Logia Cuscatlán y en la otra el emblema del COMACA LVII. Pieza de alto valor simbólico para coleccionistas de numismática masónica.',600,45),
('Moneda Conmemorativa de la Gran Logia de Honduras y R∴L∴S∴ Fraternidad No. 10','Moneda conmemorativa de tamaño mediano y acabado dorado, que presenta en una de sus caras el emblema de la Gran Logia de Honduras y, en la otra, el distintivo de la R∴L∴S∴ Fraternidad No. 10.
